import os
import requests

def validate_document_fields(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.getenv("MINDSTEE_API_KEY")
    if not api_key:
        raise ValueError("Missing API key. Set MINDSTEE_API_KEY or pass config['api_key'].")

    required_fields = config.get("required_fields")
    if not required_fields or not isinstance(required_fields, (list, tuple)):
        raise ValueError("config['required_fields'] must be a non-empty list of field names.")

    endpoint = config.get("endpoint", "https://api.mindee.net/v1/products/mindee/invoices/v4/predict")
    file_bytes = payload.get("file_bytes")
    file_path = payload.get("file_path")

    if file_bytes is not None:
        filename = payload.get("filename", "document.pdf")
        files = {"document": (filename, file_bytes, payload.get("content_type", "application/octet-stream"))}
        response = requests.post(
            endpoint,
            headers={"Authorization": f"Token {api_key}"},
            files=files,
            timeout=config.get("timeout", 60),
        )
    elif file_path:
        with open(file_path, "rb") as f:
            files = {"document": (os.path.basename(file_path), f, payload.get("content_type", "application/octet-stream"))}
            response = requests.post(
                endpoint,
                headers={"Authorization": f"Token {api_key}"},
                files=files,
                timeout=config.get("timeout", 60),
            )
    else:
        raise ValueError("payload must include either 'file_bytes' or 'file_path'.")

    response.raise_for_status()
    raw = response.json()

    prediction = (
        raw.get("document", {})
        .get("inference", {})
        .get("prediction", {})
    )

    aliases = {
        "invoice_number": ["invoice_number"],
        "supplier_name": ["supplier_name"],
        "customer_name": ["customer_name"],
        "invoice_date": ["date", "invoice_date"],
        "due_date": ["due_date"],
        "total_amount": ["total_amount", "total_incl"],
        "subtotal": ["total_excl", "subtotal"],
        "tax_amount": ["total_tax", "tax_amount"],
        "currency": ["locale", "currency"],
    }

    confidence_threshold = float(config.get("confidence_threshold", 0.0))
    fields = {}
    missing = []
    low_confidence = []

    for required in required_fields:
        candidates = aliases.get(required, [required])
        extracted_value = None
        extracted_confidence = None

        for key in candidates:
            item = prediction.get(key)
            if item is None:
                continue

            if isinstance(item, dict):
                if "value" in item:
                    extracted_value = item.get("value")
                elif "amount" in item:
                    extracted_value = item.get("amount")
                elif "content" in item:
                    extracted_value = item.get("content")
                elif "confidence" in item and len(item) == 1:
                    extracted_value = None

                extracted_confidence = item.get("confidence")
                if key == "locale" and isinstance(item, dict):
                    extracted_value = item.get("currency") or extracted_value
            else:
                extracted_value = item
                extracted_confidence = None

            if extracted_value not in (None, "", []):
                break

        present = extracted_value not in (None, "", [])
        valid = present and (extracted_confidence is None or extracted_confidence >= confidence_threshold)

        if not present:
            missing.append(required)
        elif extracted_confidence is not None and extracted_confidence < confidence_threshold:
            low_confidence.append(required)

        fields[required] = {
            "value": extracted_value,
            "confidence": extracted_confidence,
            "present": present,
            "valid": valid,
        }

    result = {
        "provider": "mindee",
        "model": "mindee/invoices/v4",
        "valid": len(missing) == 0 and len(low_confidence) == 0,
        "required_fields": list(required_fields),
        "confidence_threshold": confidence_threshold,
        "fields": fields,
        "missing_fields": missing,
        "low_confidence_fields": low_confidence,
        "raw_response": raw,
    }
    return result
